import { readFile } from "node:fs/promises";

const bytes = await readFile("./fixtures/hello.html");
const htmlBlob = new Blob([bytes], { type: "text/html" });
const form = new FormData();
form.append("file", htmlBlob, "hello.html");

const response = await fetch("http://localhost:3001/api/v1/artifacts", {
  method: "POST",
  headers: { Authorization: `Bearer ${process.env.FACTROVE_API_KEY}` },
  body: form,
});

import { readFile } from "node:fs/promises";

const artifactId = process.env.ARTIFACT_ID;
const API_ORIGIN = "http://localhost:3001";

const bytes = await readFile("./fixtures/hello.html");
const htmlBlob = new Blob([bytes], { type: "text/html" });
const form = new FormData();
form.append("file", htmlBlob, "hello.html");

const response = await fetch(`${API_ORIGIN}/api/v1/artifacts/${artifactId}/content`, {
  method: "PUT",
  headers: { Authorization: `Bearer ${process.env.FACTROVE_API_KEY}` },
  body: form,
});
